CREATE POLICY paid_vehicle_display ON public.posts AS RESTRICTIVE FOR SELECT TO anon,authenticated USING(module <> 'vehicle' OR user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_paid_bell(auth.uid()));
CREATE OR REPLACE FUNCTION public.get_post_details(_post uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN SELECT * INTO p FROM public.posts WHERE id=_post AND (user_id=auth.uid() OR (status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id))); IF p.id IS NULL THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; IF p.module='vehicle' AND NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN jsonb_build_object('description',p.description,'goods_type',p.goods_type,'capacity_tons',p.capacity_tons,'trip_date',p.trip_date); END $$;
CREATE OR REPLACE FUNCTION public.list_anonymous_bell_board(_section text) RETURNS TABLE(id uuid,source text,area text,need text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'ACCOUNT_REQUIRED'; END IF; IF _section IN('goods','returns','cars') THEN IF NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; RETURN QUERY SELECT d.id,'vehicle'::text,d.from_place||' → '||d.to_place,d.vehicle_type FROM public.vehicle_bell_demands d WHERE d.category=_section AND public.account_allowed(d.user_id) ORDER BY d.rang_at DESC; ELSE RETURN QUERY SELECT i.id,'post'::text,i.area,i.need FROM public.post_bell_interests i WHERE i.section=_section AND public.account_allowed(i.user_id) ORDER BY i.created_at DESC; IF _section='service-providers' THEN RETURN QUERY SELECT r.id,'service'::text,r.area,r.service FROM public.service_requests r WHERE public.account_allowed(r.user_id) ORDER BY r.created_at DESC; END IF; END IF; END $$;
CREATE FUNCTION public.list_area_bell_board(_section text,_area text) RETURNS TABLE(id uuid,source text,area text,need text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _section IN('goods','returns','cars') AND NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF trim(coalesce(_area,''))='' THEN RETURN; END IF; RETURN QUERY SELECT b.id,b.source,b.area,b.need FROM public.list_anonymous_bell_board(_section) b WHERE (b.source<>'vehicle' AND lower(trim(b.area))=lower(trim(_area))) OR (b.source='vehicle' AND EXISTS(SELECT 1 FROM public.vehicle_bell_demands d WHERE d.id=b.id AND lower(trim(d.from_place))=lower(trim(_area)))); END $$;
REVOKE ALL ON FUNCTION public.list_area_bell_board(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_area_bell_board(text,text) TO authenticated;